export interface Category {
  slug: string
  name: string
  nameEn: string
  description: string
}

export interface ArticleImageBlock {
  images: string[]
}

export interface ArticleCaptionBlock {
  caption: string
}

export interface ArticleHeadingBlock {
  heading: string
  /** 1 = 大標 (major section heading), 2 = 小標 (sub-heading). Defaults to 1. */
  level?: 1 | 2
}

export interface ArticleExternalLink {
  /** A clickable external-link button nested as a sub-bullet (e.g. an official booking site referenced inline in the docx via a real Word hyperlink field). */
  linkText: string
  url: string
}

export interface ArticleListItem {
  text: string
  /** Nested second-level bullets under this item (e.g. transport modes under "交通與停車方式：") — plain strings, or an ArticleExternalLink for a clickable sub-bullet. */
  sub?: (string | ArticleExternalLink)[]
}

export interface ArticleListBlock {
  /** A bullet list, optionally two-level, matching docx paragraphs with a bullet/hanging-indent list style. */
  items: (string | ArticleListItem)[]
  /** Use numbered (1/2/3) markers instead of bullets — for lists whose order is meaningful, e.g. numbers that match labels on an accompanying map image. */
  ordered?: boolean
}

export interface ArticleInfoBoxBlock {
  /** A highlighted quick-facts box (address, hours, price, etc.) rendered as a shaded bullet list — matches a docx "旅遊懶人包"-style callout box. Items can be plain strings, or an ArticleListItem (e.g. a "官方網站：" row with a clickable ArticleExternalLink button nested in `sub`). */
  infoBox: (string | ArticleListItem)[]
}

export interface ArticleRelatedBlock {
  /** Article ids to recommend as a "延伸閱讀" box at this position — for internal linking to topically/geographically related articles. */
  related: string[]
}

export interface Article {
  id: string
  category: string
  title: string
  date: string
  location: string
  /** Country name for categories that mix multiple countries (global, food) — powers the country filter on those category pages. Omitted for single-country categories (taiwan, japan, ...). */
  country?: string
  /** Prefecture/city name (e.g. '東京', '名古屋') — powers the 縣市 filter row on category pages, e.g. japan. */
  region?: string
  /** Season-limited label (e.g. '秋季限定', '冬季限定') for content tied to a specific season — powers the season filter row. Omitted for year-round content. */
  season?: string
  seed: string
  /** Real hero photo path (e.g. '/images/<id>/DSCxxxxx.jpg'). Falls back to a picsum seed placeholder when absent. */
  hero?: string
  body: (string | ArticleImageBlock | ArticleCaptionBlock | ArticleHeadingBlock | ArticleListBlock | ArticleInfoBoxBlock | ArticleRelatedBlock)[]
}

