          '大眾交通：可搭乘地方公車 18-742 線路，由 Moskenes 渡輪碼頭或 Reine 雷訥小鎮搭乘前往 Å 終點站，但整個島上的公車班次較少，建議先確認時刻表並提前做好備案安排。',
