      '雖然小鎮並不大，但卻非常有生活感，路上隨處可見掛在家門口曬的鱈魚頭，可惜淡季前往、鎮上的傳統老麵包店（Bakeriet på Å）沒有營業，所以沒能吃到肉桂捲！但是兩個人一起在小鎮裡慢慢散步，還是感受到這裡簡單的幸福。',
