      '在 42 樓買好票後，即可順著手扶梯登上 44 至 46 樓的露天開放空間。踏入觀景台的瞬間，清冽的空氣與徐徐吹過的夜風隨即包圍全身。這裡採用雙層玻璃與開放式頂棚設計，幾乎是360度毫無死角，能見到名古屋塔（Mirai Tower）、JR 中央塔以及遠處延綿不絕的車流交織成一條條流動的城市光河。',
      '💡小知識科普：Midland Square（中部地方廣場）是日本中部地方最高的摩天大樓，總高度達 247 公尺！其 44 至 46 樓的 Sky Promenade 是全日本少見的「露天/半戶外高空觀景台」，設計上利用特殊的玻璃牆阻擋強風，同時保留頂級的開闊感與自然通風，讓遊客能體驗到最真實的城市氣息。',
