      '白日夢小提醒：手羽先的胡椒粉稍微帶有微辣感，不吃辣的朋友在點餐時可以挑選鹽味，整體而言調味較為濃郁偏鹹，所以建議多點一杯烏龍茶或冰啤酒解膩喔！',
