export function articlesByCategory(slug: string): Article[] {
  return articles
    .filter(a => a.category === slug)
    .sort((a, b) => b.date.localeCompare(a.date))
}

export function categoryBySlug(slug: string): Category | undefined {
  return categories.find(c => c.slug === slug)
}

/** 分類/導覽名稱格式為「中文．中文ENGLISH」，取尾端連續大寫字母當作英文行，其餘當中文行。 */
export function splitCategoryName(label: string): { zh: string; en: string } {
  const match = label.match(/^(.*?)([A-Z]+)$/)
  if (!match) return { zh: label, en: '' }
  const en = match[2]
  return { zh: match[1], en: en.charAt(0) + en.slice(1).toLowerCase() }
}

export function articleById(category: string, id: string): Article | undefined {
  return articles.find(a => a.category === category && a.id === id)
}

/** First prose paragraph of the article body, used as the card/preview excerpt. */
export function articleExcerpt(article: Article): string {
  const first = article.body.find((block): block is string => typeof block === 'string')
  return first ?? ''
}

/** articleExcerpt() trimmed to a search-snippet-friendly length, for <meta name="description">/og:description. */
export function articleMetaDescription(article: Article): string {
  const excerpt = articleExcerpt(article)
  const limit = 120
  return excerpt.length > limit ? `${excerpt.slice(0, limit)}…` : excerpt
}
